  "anhalt-university": [{"src": "assets/img/universities/anhalt-university/1.jpg", "title": "Hochschule Anhalt Köthen Tafel zum Gedenken an die aufgelöste Technische Hochschule Köthen Aufnahme und Copyright MEH Bergmann", "caption": "Mit der Neugründung des Landes Sachsen-Anhalt war auch eine Neustrukturierung der Hochschullandschaft verbunden, die finanziell nur Raum für zwei universitäre Einrichtungen in Halle/Wittenberg (Volluniversität) und Magdeburg (Technische Universität) ließ. Die Technische Hochschule Köthen, die in der", "artist": "MEH Bergmann", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "page": "https://commons.wikimedia.org/wiki/File%3AHochschule_Anhalt_K%C3%B6then_Tafel_zum_Gedenken_an_die_aufgel%C3%B6ste_Technische_Hochschule_K%C3%B6then_Aufnahme_und_Copyright_MEH_Bergmann.jpg"}, {"src": "assets/img/universities/anhalt-university/2.jpg", "title": "Hochschule Anhalt neu gestalteter Außenbereich der Mensa Aufnahme und Copyright MEH Bergmann", "caption": "Im Bemühen, dem Hochschulstandort Köthen ein moderneres Ausshen zu geben, wurde nach der Jahrtausendwende auch der Außenbereich der Mensa (rechts im Bild) mit der Terasse neu gestaltet. Die Gebäude im Hintergrund sind Wohnheime an der Bernburger Straße.", "artist": "MEH Bergmann", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "page": "https://commons.wikimedia.org/wiki/File%3AHochschule_Anhalt_neu_gestalteter_Au%C3%9Fenbereich_der_Mensa_Aufnahme_und_Copyright_MEH_Bergmann.jpg"}, {"src": "assets/img/universities/anhalt-university/3.jpg", "title": "Technische Hochschule Köthen - Hochschule Anhalt - Ruhebereich Aufnahme und Copyright MEH Bergmann", "caption": "Der Ruhebereich am Verwaltungsgebäude 02 an der Bernburger Straße 55 wurde durch den damaligen Rektor der Technischen Hochschule, Kurt Gramlich, in der Wendezeit initiert. Der Bereich zwischen einem Wohnheim und dem Verwaltungstrakt besitzt eine Wiese, ein angedeutetes Amphietheater, Sitzgelegenheit", "artist": "MEH Bergmann", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "page": "https://commons.wikimedia.org/wiki/File%3ATechnische_Hochschule_K%C3%B6then_-_Hochschule_Anhalt_-_Ruhebereich_Aufnahme_und_Copyright_MEH_Bergmann.jpg"}],
